import{_ as e,o,c as a,a2 as i}from"./chunks/framework.CZo9GF0W.js";const p=JSON.parse('{"title":"Google Cloud SQL","description":"","frontmatter":{},"headers":[],"relativePath":"recipes/cloud-sql.md","filePath":"recipes/cloud-sql.md","lastUpdated":1789060268000}'),n={name:"recipes/cloud-sql.md"};function r(s,t,d,h,c,l){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="google-cloud-sql" tabindex="-1">Google Cloud SQL <a class="header-anchor" href="#google-cloud-sql" aria-label="Permalink to &quot;Google Cloud SQL&quot;">​</a></h1><p>Three ways in, in increasing order of how much you have to set up.</p><h2 id="_1-the-cloud-sql-auth-proxy-recommended" tabindex="-1">1. The Cloud SQL Auth Proxy (recommended) <a class="header-anchor" href="#_1-the-cloud-sql-auth-proxy-recommended" aria-label="Permalink to &quot;1. The Cloud SQL Auth Proxy (recommended)&quot;">​</a></h2><p>The proxy authenticates with your Google credentials, encrypts the connection itself, and listens on a local port. Pitta then connects to what looks like a plain local database.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloud-sql-proxy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5432</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-project:europe-west1:orders</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Host</td><td><code>localhost</code></td></tr><tr><td>Port</td><td><code>5432</code></td></tr><tr><td>Database</td><td>your database</td></tr><tr><td>User</td><td>the Cloud SQL user</td></tr><tr><td>SSL mode</td><td><code>disable</code></td></tr><tr><td>Environment</td><td>whatever it really is — <code>prod</code> if the <em>instance</em> is production</td></tr></tbody></table><p><code>disable</code> is right here: the proxy is doing the TLS, and the hop Pitta makes is loopback. Do not confuse &quot;the socket is plaintext&quot; with &quot;the connection is plaintext&quot;; the proxy&#39;s own connection to Cloud SQL is mutually authenticated and encrypted.</p><div class="warning custom-block"><p class="custom-block-title">Where does the proxy run?</p><p>On the machine VS Code&#39;s workspace is on. Under Remote-SSH, start the proxy on the remote, not on your laptop — otherwise <code>localhost:5432</code> on the remote is nothing at all. See <a href="/pitta-db/guide/remote">Remote development</a>.</p></div><p>Tag the profile by the <em>instance&#39;s</em> environment. A proxy to production is production, however local the port looks.</p><h2 id="_2-iam-database-authentication-through-the-proxy" tabindex="-1">2. IAM database authentication through the proxy <a class="header-anchor" href="#_2-iam-database-authentication-through-the-proxy" aria-label="Permalink to &quot;2. IAM database authentication through the proxy&quot;">​</a></h2><p>Run the proxy with <code>--auto-iam-authn</code>, and use your IAM principal as the user — for a service account, the email with <code>.gserviceaccount.com</code> stripped. The password field is then unused; the proxy supplies the token.</p><h2 id="_3-a-direct-connection-with-a-public-ip" tabindex="-1">3. A direct connection with a public IP <a class="header-anchor" href="#_3-a-direct-connection-with-a-public-ip" aria-label="Permalink to &quot;3. A direct connection with a public IP&quot;">​</a></h2><p>Only if the proxy is genuinely not an option. Authorize the connecting address in the instance&#39;s authorized networks — under Remote-SSH that is the remote&#39;s egress address — and download the server CA from the instance&#39;s <strong>Connections → Security</strong> page.</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Host</td><td>the instance&#39;s public IP</td></tr><tr><td>Port</td><td>5432 · MySQL 3306 · SQL Server 1433</td></tr><tr><td>SSL mode</td><td><code>verify-ca</code></td></tr><tr><td>CA certificate</td><td><code>~/.certs/cloudsql-server-ca.pem</code></td></tr></tbody></table><p><code>verify-ca</code> rather than <code>verify-full</code>: you are connecting to an IP address, and full verification checks the hostname against the certificate. If the instance requires client certificates, add the client certificate and key alongside.</p><p>Turning on <strong>Require SSL</strong> for the instance is worth doing regardless. It stops a plaintext connection existing at all rather than relying on every client to choose well.</p><h2 id="private-ip" tabindex="-1">Private IP <a class="header-anchor" href="#private-ip" aria-label="Permalink to &quot;Private IP&quot;">​</a></h2><p>If the instance has a private IP, connect from something in the same VPC — a VM you attach to over Remote-SSH is the tidiest — or through <a href="./ssh">an SSH bastion</a>.</p><h2 id="things-that-look-like-bugs" tabindex="-1">Things that look like bugs <a class="header-anchor" href="#things-that-look-like-bugs" aria-label="Permalink to &quot;Things that look like bugs&quot;">​</a></h2><ul><li><strong><code>connection refused</code> on localhost.</strong> The proxy is not running, or is running on a different machine from the one Pitta is on.</li><li><strong>Proxy exits immediately.</strong> Check its own output: usually credentials, or the Cloud SQL Admin API not being enabled on the project.</li><li><strong>IAM user fails to authenticate.</strong> The IAM user has to exist <em>in the instance</em> as a database user as well as in IAM. Both halves are needed.</li></ul>',20)])])}const m=e(n,[["render",r]]);export{p as __pageData,m as default};
